def mensajes_de_este_turno(ruta):
    """Cuenta los mensajes ESCRITOS por el asistente despues del ultimo renglon user.

    Fallo del 2026-09-25, confirmado por Julio enojado ese mismo dia: sigue recibiendo
    dos mensajes cada vez que pregunta, porque tras el primer mensaje un candado obliga
    a guardar y despues se le escribe otro.

    Entiende las dos formas:
      - la sencilla: renglon con clave type y clave text.
      - la de verdad de Claude Code: type == 'assistant' y el texto vive en message,
        en su lista content, en los pedazos cuyo type es 'text'.
    No cuenta: renglones del asistente que solo llevan llamadas a herramientas, ni el
    texto vacio. Si el archivo no existe o no se puede leer, devuelve cero. Nunca revienta.
    """
    try:
        with open(ruta, "r", encoding="utf-8") as f:
            renglones = f.readlines()
    except Exception:
        return 0

    ultimo_user = -1
    for i, linea in enumerate(renglones):
        try:
            dato = json.loads(linea)
        except Exception:
            continue
        if isinstance(dato, dict) and dato.get("type") == "user":
            ultimo_user = i

    cuenta = 0
    for linea in renglones[ultimo_user + 1:]:
        try:
            dato = json.loads(linea)
        except Exception:
            continue
        if not isinstance(dato, dict):
            continue
        if dato.get("type") != "assistant":
            continue
        if _tiene_texto_escrito(dato):
            cuenta += 1
    return cuenta


def _tiene_texto_escrito(dato):
    """True si el renglon del asistente lleva texto escrito de verdad."""
    texto = dato.get("text")
    if isinstance(texto, str) and texto.strip():
        return True
    mensaje = dato.get("message")
    if isinstance(mensaje, dict):
        contenido = mensaje.get("content")
        if isinstance(contenido, list):
            for pedazo in contenido:
                if not isinstance(pedazo, dict):
                    continue
                if pedazo.get("type") != "text":
                    continue
                t = pedazo.get("text")
                if isinstance(t, str) and t.strip():
                    return True
    return False

